const content = $json.content ?? [];
const toolUse = content.find(b => b.type === 'tool_use' && b.name === 'submit_post');
if (!toolUse) {
  throw new Error('Claude応答にtool_useブロックが見つかりませんでした: ' + JSON.stringify(content).slice(0, 300));
}
const p = toolUse.input;
const src = $('パターンガイド付与').first().json;

const JST_OFFSET_MS = 9 * 60 * 60 * 1000;
const nowJST = new Date(Date.now() + JST_OFFSET_MS);
const pad = (v) => String(v).padStart(2, '0');
const revisedAtJst = `${nowJST.getUTCFullYear()}-${pad(nowJST.getUTCMonth() + 1)}-${pad(nowJST.getUTCDate())} ${pad(nowJST.getUTCHours())}:${pad(nowJST.getUTCMinutes())}`;

return [{
  json: {
    page_id: src.id,
    pattern_used: p.pattern_used ?? '',
    hook: p.hook ?? '',
    body: p.body ?? '',
    cta: p.cta ?? '',
    hashtags: Array.isArray(p.hashtags) ? p.hashtags.join(', ') : (p.hashtags ?? ''),
    image_prompt: p.image_prompt ?? '',
    platform: src.property_platform,
    name: src.property_name,
    // 修正前の内容(Notionページ本文への履歴追記用。プロパティ上書き前の値をここで保持しておく)
    previous_pattern_used: src.property_pattern_used ?? '',
    previous_hook: src.property_hook ?? '',
    previous_body: src.property_body ?? '',
    previous_cta: src.property_cta ?? '',
    previous_hashtags: src.property_hashtags ?? '',
    previous_image_prompt: src.property_image_prompt ?? '',
    revision_memo: src.property_revision_memo ?? '',
    revised_at_jst: revisedAtJst
  }
}];
